export function driveChildUsage(paths: CellPaths, sessionIds: string[]): Omit<Usage, "reported_cost_usd"> | null {
  const proj = join(CLAUDE_CONFIG, "projects", paths.repo.replace(/[^a-zA-Z0-9]/g, "-"))
  const files: string[] = []
  for (const sid of new Set(sessionIds)) {
    files.push(join(proj, `${sid}.jsonl`))
    const sub = join(proj, sid, "subagents")
    if (existsSync(sub)) for (const f of new Bun.Glob("*.jsonl").scanSync(sub)) files.push(join(sub, f))
  }
  const per = new Map<string, number[]>()
  const keys = ["input_tokens", "cache_creation_input_tokens", "cache_read_input_tokens", "output_tokens"] as const
  let found = 0
  for (const file of files) {
    if (!existsSync(file)) continue
    found++
    for (const line of readFileSync(file, "utf8").split("\\n")) {
      if (!line.includes('"usage"')) continue
      let e: { type?: string; requestId?: string; message?: { id?: string; usage?: Record<string, number> } }
      try {
        e = JSON.parse(line)
      } catch {
        continue
      }
      if (e.type !== "assistant") continue
      const u = e.message?.usage ?? {}
      const id = `${e.message?.id}|${e.requestId}`
      const rec = per.get(id) ?? [0, 0, 0, 0]
      keys.forEach((k, i) => {
        rec[i] = Math.max(rec[i] ?? 0, u[k] ?? 0)
      })
      per.set(id, rec)
    }
  }
  if (!found) return null
  const sum = (i: number) => [...per.values()].reduce((a, r) => a + (r[i] ?? 0), 0)
  return { input_tokens: sum(0), cache_creation_tokens: sum(1), cache_read_tokens: sum(2), output_tokens: sum(3) }
